INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind lokale IT-Systeme immer teurer als Cloud-Lösungen?', 2, '[{"text": "Nein", "correct": true, "because": "Kosten hängen von Nutzung ab"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig teurer"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil, wenn ich meine IT-Ressourcen vor Ort betreibe?', 3, '[{"text": "Volle Kontrolle", "correct": true, "because": "Direkter Zugriff auf Systeme"}, {"text": "Minimale Wartung", "correct": false, "because": "Wartung nötig"}, {"text": "Automatische Skalierung", "correct": false, "because": "Cloud-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale machen lokale IT-Systeme attraktiv?', 5, '[{"text": "Datensouveränität", "correct": true, "because": "Daten bleiben vor Ort"}, {"text": "Anpassbarkeit", "correct": true, "because": "Individuelle Konfiguration möglich"}, {"text": "Hohe Latenz", "correct": false, "because": "Eher ein Nachteil"}, {"text": "Keine Wartung", "correct": false, "because": "Wartung erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Lokale Systeme bieten direkten Zugriff. b) Sie sind immer wartungsfrei.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Wartung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Planung eines lokalen IT-Systems?', 4, '[{"text": "Sicherheitsmaßnahmen", "correct": false, "because": "Schützen Systeme"}, {"text": "Hardwarekapazität", "correct": false, "because": "Bestimmt Leistung"}, {"text": "Bürogestaltung", "correct": true, "because": "Irrelevant für IT"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob lokale Systeme immer Internet benötigen?', 2, '[{"text": "Nein", "correct": true, "because": "Können offline laufen"}, {"text": "Ja", "correct": false, "because": "Internet optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium ist für lokale IT-Systeme entscheidend?', 3, '[{"text": "Redundanz", "correct": true, "because": "Sichert Verfügbarkeit"}, {"text": "Cloud-Integration", "correct": false, "because": "Nicht primär"}, {"text": "Manuelle Skalierung", "correct": false, "because": "Zu aufwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen sichern den Betrieb lokaler Systeme?', 5, '[{"text": "Regelmäßige Backups", "correct": true, "because": "Schützen vor Datenverlust"}, {"text": "Patch-Management", "correct": true, "because": "Schließt Sicherheitslücken"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Sekundär"}, {"text": "Cloud-Backups", "correct": false, "because": "Nicht On-Premises"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass lokale Systeme immer sicherer sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Sicherheit hängt von Maßnahmen ab"}, {"text": "Ja", "correct": false, "because": "Nicht automatisch sicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Einrichtung eines lokalen Servers?', 4, '[{"text": "Stromversorgung", "correct": true, "because": "Sichert Betrieb"}, {"text": "Minimaler Platzbedarf", "correct": false, "because": "Sekundär"}, {"text": "Manuelle Updates", "correct": false, "because": "Automatisierung besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Lokale Systeme erlauben Anpassungen. b) Sie skalieren automatisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist Cloud-spezifisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature finde ich bei lokalen IT-Systemen entscheidend?', 4, '[{"text": "Direkte Hardwarekontrolle", "correct": true, "because": "Ermöglicht Optimierung"}, {"text": "Automatische Skalierung", "correct": false, "because": "Cloud-Vorteil"}, {"text": "Minimale Wartung", "correct": false, "because": "Wartung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass lokale Systeme keine Internetverbindung brauchen. Stimmt das?', 3, '[{"text": "Ja", "correct": true, "because": "Viele Anwendungen laufen offline"}, {"text": "Nein", "correct": false, "because": "Internet oft optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein lokales IT-System?', 3, '[{"text": "Stromversorgung", "correct": false, "because": "Essenziell für Betrieb"}, {"text": "Sicherheitsupdates", "correct": false, "because": "Schützen Systeme"}, {"text": "Cloud-Abo", "correct": true, "because": "Nicht On-Premises"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind lokale Systeme immer langsamer?', 2, '[{"text": "Nein", "correct": true, "because": "Leistung hängt von Hardware ab"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig langsamer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein lokales IT-System?', 4, '[{"text": "Datenschutzkontrolle", "correct": true, "because": "Daten bleiben intern"}, {"text": "Flexible Hardwarewahl", "correct": true, "because": "Anpassung an Bedarf"}, {"text": "Echtzeit-Skalierung", "correct": false, "because": "Cloud-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob lokale Systeme für alle Unternehmen geeignet sind?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Bedarf"}, {"text": "Ja", "correct": false, "because": "Nicht universell passend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Wartung eines lokalen Systems wichtig?', 3, '[{"text": "Regelmäßige Updates", "correct": true, "because": "Sichern Stabilität"}, {"text": "Cloud-Backups", "correct": false, "because": "Nicht On-Premises"}, {"text": "Manuelle Konfiguration", "correct": false, "because": "Automatisierung besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erfordern lokale Systeme immer hohe Anfangskosten?', 3, '[{"text": "Ja", "correct": true, "because": "Hardwareinvestition nötig"}, {"text": "Nein", "correct": false, "because": "Kosten oft hoch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einem lokalen IT-System?', 4, '[{"text": "Sensible Datenverarbeitung", "correct": true, "because": "Maximale Kontrolle"}, {"text": "Echtzeit-Cloud-Analysen", "correct": false, "because": "Cloud-spezifisch"}, {"text": "Minimaler Wartungsaufwand", "correct": false, "because": "Wartung nötig"}]');
